definition.script:
pipeline {
    agent {label 'agent-1'}

    parameters{
        string(name:'Deploy_Env', defaultValue:'dev', description:'Deployment to')
        booleanParam(name:'RUN_TEST', defaultValue:'true', description:'Run Tests?')
    }

    environment{
        REGION = 'ap-south-1'
        BUILD_VERSION = '1.0${BUILD_NUMBER}'
    }

    stages {
        stage('Built In Variables') {
            steps {
                echo "Build_ID : ${env.BUILD_ID}" 
                echo "Build_Number : ${env.BUILD_NUMBER}" 
                echo "Workspace : ${env.WORKSPACE}" 
                echo "Node Name : ${env.NODE_NAME}" 
            }
        }

        stage('Parameters') {
            steps {
                echo "Deploy_env : ${params.DEPLOY_ENV}" 
                echo "Run_Test : ${params.RUN_TEST}" 

            }
        }

        stage('Custom Variables/Environment Vars') {
            steps {
                echo "REGION : ${env.REGION}" 
                echo "BUILD_VERSION : ${env.BUILD_VERSION}" 

            }
        }

        stage('Dynamic Custom Variables') {
            steps {
                script{
                env.RUNTIME_VAR = "runtime-${env.BUILD_NUMBER}"
                echo "Dynamic : ${env.RUNTIME_VAR}" 
                }
            }
        }
    }
}
